CONTACT_FIELDS = ("name", "company_name", "phone", "email",
                  "address", "city", "lat", "lng", "notes")


def give_converted_leads_their_customer(apps, schema_editor):
    """A lead marked converted but with no customer (#25) gets the customer
    record converting would have made. "Converted" means a customer exists;
    this makes that true for the few saved before the rule was enforced."""
    Lead = apps.get_model("crm", "Lead")
    Customer = apps.get_model("crm", "Customer")
    for lead in Lead.objects.filter(status="converted", converted_customer__isnull=True):
        customer = Customer.objects.create(
            **{f: getattr(lead, f) for f in CONTACT_FIELDS},
            assigned_to_id=lead.assigned_to_id,
            created_by_id=lead.created_by_id,
            customer_since=(lead.converted_at or lead.updated_at or timezone.now()).date(),
        )
        lead.converted_customer = customer
        if lead.converted_at is None:
            lead.converted_at = lead.updated_at
        lead.save(update_fields=["converted_customer", "converted_at"])


